export interface GeoPart {
  way: number;
  version: number;
  coordinates: [number, number][];
  bottom: number;
  top: number;
  estimatedHeight?: boolean;
  roofSlope?: { direction: number; height: number };
  crown?: { eave: number; peak: number; tip: number };
}

export interface GeoBuilding {
  id: string;
  name: string;
  shortName: string;
  height: number;
  tipHeight: number;
  heightSource: string;
  // Set where no height is published and the model's is read on the drawing; the
  // source then gives the storeys the reading was checked against.
  heightFromDrawing?: boolean;
  note: string;
  footprint: { way: number; version: number; coordinates: [number, number][] };
  parts: GeoPart[];
}

export interface GeoStreet {
  way: number;
  version: number;
  name: string;
  coordinates: [number, number][];
}


